import loggingimport discordfrom discord import Colorfrom discord.ext import commandsimport mysql.connectorfrom print_color import printfrom db_services.MysqlServices import get_banned_words_from_db, delete_banned_word_from_db, add_banned_word_to_dbfrom utils.EmbedGeneratorUtil import EmbedGeneratorfrom utils.custom.errors.FingerBangThePoonTangBotError import EmptyWordStringError, UnknownCommandFailure, \    WordNotBannedErrorclass BannedWordsCommands(commands.Cog):    def __init__(self, bot: commands.Bot):        self.bot = bot        self.logger = logging.getLogger('discord')    @commands.has_role("Bot Admin")    @commands.command(name="bannedwords", help="Shows A List Of All The Banned Words Added To The Database.'")    async def bannedwords(self, ctx: discord.ext.commands.Context):        """        Shows a list of banned words that have been added to the database by a user with the role 'Bot Admin'        :param ctx: This is the discord Interaction we can access data from.        :return:        """        word_list = await get_banned_words_from_db(host=self.bot.db_host, user=self.bot.db_user, password=self.bot.db_pass, database=self.bot.db_db_name)        string_all = ""        for x in word_list:            string_all += str("||" + x[0] + "||\n")        embed = EmbedGenerator(self.bot).generate_simple_message_embed(description=string_all, colour=Color.blurple())        await ctx.reply(embed=embed, mention_author=False)    @commands.has_role("Bot Admin")    @commands.command(name="addbannedword", help="Adds A New Word To The 'banned_words' DB")    async def add_banned_word(self, ctx: discord.ext.commands.Context, banned_word: str = commands.Parameter(name='banned_word', description="The Word In Which You Would Like Banned", kind=commands.Parameter.KEYWORD_ONLY)):        """        Adds a new word to the 'banned_words' DB and returns an embed with the word that was banned.        :param ctx: This is the discord Interaction we can access data from.        :param banned_word: The word in which you would like to ban.        :return:        """        if banned_word is None:            raise EmptyWordStringError(error="You Must Input A Valid Word To Be Banned!")        try:            await add_banned_word_to_db(self.bot.db_host, self.bot.db_user, self.bot.db_pass, self.bot.db_db_name, banned_word)            embed = EmbedGenerator(self.bot).generate_simple_message_embed(                description=f"Successfully Added Word ||{banned_word}|| To banned_words DB!", colour=Color.green())            await ctx.reply(embed=embed, mention_author=False)        except Exception as e:            print(e, tag="FAILURE", tag_color="red", color="red")            self.logger.info("[FAILURE] There Has Been A Failure At Line 49-57 in BannedWordsCommands.py")            raise UnknownCommandFailure(error=e)    @commands.has_role("Bot Admin")    @commands.command(name="delbannedword", help="Deletes A Word From The 'banned_words' DB And Returns An Embed With The Newly Unbanned Word.")    async def delete_banned_word(self, ctx: discord.Interaction, banned_word: str = commands.Parameter(name="banned_word", description="The Word In Which You Would Like To Unban.", kind=commands.Parameter.KEYWORD_ONLY)):        """        Deletes a new word from the 'banned_words' DB and returns an embed with the word that was unbanned.        :param ctx: This is the discord Interaction we can access data from.        :param banned_word: The word in which you would like to unban.        :return:        """        if banned_word is None:            raise EmptyWordStringError(error="You Must Input A Valid Word To Be Unbanned!")        try:            if await delete_banned_word_from_db(self.bot.db_host, self.bot.db_user, self.bot.db_pass, self.bot.db_db_name, banned_word):                embed = EmbedGenerator(self.bot).generate_simple_message_embed(                    description=f"Successfully Removed Word {banned_word} From banned_words DB!", colour=Color.green())                await ctx.reply(embed=embed, mention_author=False)            else:                raise WordNotBannedError(error="This Word Is Not Currently Banned, So It Cannot Be Unbanned!")        except Exception as e:            print(e, tag="FAILURE", tag_color="red", color="red")            self.logger.info("[FAILURE] There Has Been A Failure At Line 73-83 in BannedWordsCommands.py")            raise UnknownCommandFailure(error=e)async def setup(bot: commands.Bot):    await bot.add_cog(BannedWordsCommands(bot))